INSERT INTO online_directions (slug, title, short_desc, icon, color, age_groups, price_single, price_4, price_8, seo_text, sort_order) VALUES
('podgotovka-k-shkole','Подготовка к школе','Чтение, счёт, письмо, развитие речи и внимания — мягкий старт перед первым классом.','Star','from-violet-500 to-purple-600','Дошкольники 5–7 лет','1 500 ₽','5 600 ₽','10 400 ₽','Подготовка к школе онлайн: занятия с педагогом по видеосвязи, чтение, счёт и развитие речи для дошкольников.',1),
('nachalnaya-shkola','Начальная школа','Сопровождение по школьной программе 1–4 класса и уверенность на уроках.','BookOpen','from-indigo-500 to-blue-600','1–4 класс','1 500 ₽','5 600 ₽','10 400 ₽','Занятия онлайн для школьников начальных классов: русский язык, математика, чтение и окружающий мир.',2),
('russkiy-yazyk','Русский язык','Правила, грамотное письмо, разборы и работа над ошибками.','PenTool','from-rose-500 to-pink-600','1–11 класс','1 600 ₽','6 000 ₽','11 200 ₽','Репетитор онлайн по русскому языку для школьников 1–11 классов.',3),
('matematika','Математика','От устного счёта до алгебры и геометрии — по шагам и без пробелов.','Calculator','from-sky-500 to-cyan-600','1–11 класс','1 600 ₽','6 000 ₽','11 200 ₽','Репетитор онлайн по математике: устный счёт, алгебра, геометрия, подготовка к экзаменам.',4),
('angliyskiy-yazyk','Английский язык','Разговорная практика, грамматика и школьная программа.','Languages','from-amber-500 to-orange-600','Дошкольники – 11 класс','1 600 ₽','6 000 ₽','11 200 ₽','Английский язык онлайн для детей и школьников: разговорная практика и грамматика.',5),
('podgotovka-oge','Подготовка к ОГЭ','Разбор формата экзамена, типовые задания и устранение пробелов.','ClipboardCheck','from-emerald-500 to-teal-600','8–9 класс','1 800 ₽','6 800 ₽','12 800 ₽','Подготовка к ОГЭ онлайн: разбор заданий, тренировочные варианты, работа над ошибками.',6),
('podgotovka-ege','Подготовка к ЕГЭ','Системная работа по профильным предметам и тренировка на вариантах.','GraduationCap','from-fuchsia-500 to-violet-600','10–11 класс','2 000 ₽','7 600 ₽','14 400 ₽','Подготовка к ЕГЭ онлайн с опытными педагогами: профильные предметы и пробные варианты.',7),
('logoped-onlayn','Логопед онлайн','Постановка и автоматизация звуков, развитие речи и дыхания.','MessageCircle','from-teal-500 to-cyan-600','Дошкольники – 9 класс','1 800 ₽','6 800 ₽','12 800 ₽','Логопед онлайн для детей: постановка звуков, запуск и развитие речи по видеосвязи.',8),
('defektolog-onlayn','Дефектолог онлайн','Занятия для детей с особенностями развития по индивидуальной программе.','HeartHandshake','from-pink-500 to-rose-600','Дошкольники – 9 класс','1 800 ₽','6 800 ₽','12 800 ₽','Дефектолог онлайн: индивидуальные коррекционные занятия для детей с особенностями развития.',9),
('korrektsionnye-zanyatiya','Коррекционно-развивающие занятия','Внимание, память, мышление и саморегуляция в игровом формате.','Brain','from-purple-500 to-indigo-600','Дошкольники – 6 класс','1 700 ₽','6 400 ₽','12 000 ₽','Коррекционно-развивающие занятия онлайн: внимание, память, мышление и речь.',10),
('pomoshch-s-dz','Помощь с домашними заданиями','Разбираем задания вместе, объясняем непонятное и закрепляем.','NotebookPen','from-lime-500 to-emerald-600','1–11 класс','1 400 ₽','5 200 ₽','9 600 ₽','Помощь с домашними заданиями онлайн для школьников любого класса.',11),
('individualnye-zanyatiya','Индивидуальные занятия','Персональная программа и всё внимание педагога одному ученику.','User','from-blue-500 to-indigo-600','Любой возраст','1 800 ₽','6 800 ₽','12 800 ₽','Индивидуальные занятия онлайн с педагогом по персональной программе.',12),
('razvivayushchie-zanyatiya','Развивающие занятия для детей','Творчество, логика и кругозор — интересно и без перегрузки.','Sparkles','from-orange-500 to-amber-600','Дошкольники – 4 класс','1 400 ₽','5 200 ₽','9 600 ₽','Развивающие занятия онлайн для детей: логика, творчество, кругозор.',13);
INSERT INTO online_faq (question, answer, sort_order) VALUES
('Как проходят онлайн-занятия?','Занятие идёт по видеосвязи в назначенное время. Педагог работает с ребёнком по программе, использует интерактивную доску, материалы и задания на экране.',1),
('Какая платформа используется?','Мы работаем в привычных сервисах видеосвязи. Ссылку на занятие вы получаете заранее — она появляется в личном кабинете и приходит от педагога.',2),
('Нужен ли компьютер?','Компьютер или ноутбук удобнее всего: больше экран и проще работать с материалами. Но обязательным условием это не является.',3),
('Можно ли заниматься с телефона или планшета?','Да. Планшет подходит почти для всех направлений, телефон — для коротких и разговорных занятий.',4),
('Как выбрать педагога?','Посмотрите раздел «Педагоги» или оставьте заявку — специалист уточнит задачи и предложит подходящего педагога.',5),
('Можно ли изменить расписание?','Да, расписание можно скорректировать по согласованию с педагогом.',6),
('Как оплачиваются занятия?','Можно оплатить разовое занятие или абонемент на 4 или 8 занятий. Информация об оплате отображается в личном кабинете.',7),
('Есть ли пробное занятие?','Да, предусмотрено пробное занятие — на нём вы знакомитесь с педагогом и форматом работы. Условия уточняйте у администратора.',8),
('Можно ли заниматься индивидуально?','Да, индивидуальный формат доступен по всем направлениям.',9),
('Можно ли заниматься в мини-группе?','Да, мини-группы формируются по возрасту и уровню подготовки.',10);
