INSERT INTO online_reviews (author, role, text, rating, sort_order) VALUES
('Марина','мама ученика 3 класса','Занимаемся онлайн русским языком. Ребёнку удобно, а мне спокойно — видно, что программа выстроена под него.',5,1),
('Ольга','мама дошкольника','Готовимся к школе по видеосвязи. Сын занимается с удовольствием, педагог очень внимательная.',5,2),
('Дмитрий','папа ученика 9 класса','Подтягиваем математику перед ОГЭ. Пробелы разбираем по шагам, стало заметно легче.',5,3);
